import base64
import io
import os
from typing import Optional

from openai import OpenAI


def _load_image_bytes(image_input: str) -> bytes:
    if image_input.startswith(("http://", "https://")):
        import requests

        resp = requests.get(image_input, timeout=30)
        resp.raise_for_status()
        return resp.content

    if os.path.exists(image_input):
        with open(image_input, "rb") as f:
            return f.read()

    # Treat as base64-encoded image data
    try:
        return base64.b64decode(image_input, validate=True)
    except Exception as e:
        raise ValueError("image_input must be a file path, URL, or base64-encoded image bytes") from e


def generate_visual_description(image_input: str, max_words: Optional[int] = 30) -> str:
    """
    Generate a short visual description for an image using OpenAI's hosted multimodal model.
    """
    image_bytes = _load_image_bytes(image_input)
    b64 = base64.b64encode(image_bytes).decode("utf-8")
    data_url = f"data:image/jpeg;base64,{b64}"

    client = OpenAI()

    prompt = (
        "Provide a short visual description of this image in one sentence. "
        "Focus on the main subjects, scene, and notable details. "
        + (f"Keep it under {max_words} words." if max_words else "")
    )

    response = client.responses.create(
        model="gpt-4o-mini",
        input=[
            {
                "role": "user",
                "content": [
                    {"type": "input_text", "text": prompt},
                    {"type": "input_image", "image_url": data_url},
                ],
            }
        ],
    )

    text = getattr(response, "output_text", None)
    if text:
        return text.strip()

    # Fallback parsing
    try:
        parts = []
        for item in response.output:
            for content in getattr(item, "content", []):
                if getattr(content, "type", None) in ("output_text", "text"):
                    parts.append(getattr(content, "text", ""))
        return " ".join(parts).strip()
    except Exception:
        return ""
